#!/usr/bin/env bash
# protect-files: Codex PreToolUse hook for file edits (matcher "apply_patch").
# Blocks patches that add, change, move or delete dependency lock files (they are
# regenerated by their package manager) or environment files (they hold secrets).
# Reading environment files is blocked separately by the `mk96` permission profile
# in config.toml, which the sandbox enforces.
# Usage: configured in ~/.codex/hooks.json (PreToolUse, matcher "apply_patch"). Needs jq.
set -Eeuo pipefail

readonly LOCK_FILES='^(Cargo\.lock|Gemfile\.lock|composer\.lock|go\.sum|package-lock\.json|pnpm-lock\.yaml|poetry\.lock|uv\.lock|yarn\.lock)$'
readonly ENV_FILES='^\.env(\..*\.local|\.local|\.development|\.production|\.staging|\.test)?$'
# apply_patch names every touched file on one of these header lines.
readonly FILE_HEADER='^\*\*\* (Add File|Update File|Delete File|Move to): (.+)$'

main() {
  local patch line path name
  patch="$(jq -r '.tool_input.command // ""')"
  while IFS= read -r line; do
    [[ "$line" =~ $FILE_HEADER ]] || continue
    path="${BASH_REMATCH[2]}"
    name="${path##*/}"
    if [[ "$name" =~ $LOCK_FILES ]]; then
      deny "protect-files: ${path} is a lock file; change dependencies with the package manager instead of editing it."
    elif [[ "$name" =~ $ENV_FILES ]]; then
      deny "protect-files: ${path} is an environment file that may hold secrets; ask the user to edit it."
    fi
  done <<<"$patch"
}

deny() {
  jq -n --arg reason "$1" '{hookSpecificOutput: {
    hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $reason}}'
  exit 0
}

main "$@"
